#include <unistd.h>

typedef ssize_t (*readlink_fn)(const char *, char *, size_t);

/*
 * The audit container's PID namespace can expose a process-local PID that has
 * no matching /proc/<pid>/exe entry. Lean 4.22 queries that numeric entry.
 * Fall back to the kernel's equivalent /proc/self/exe only for that failed
 * read, leaving every successful read and every other path unchanged.
 */
ssize_t readlink(const char *path, char *buf, size_t size) {
    static readlink_fn real_readlink;
    if (!real_readlink) {
        real_readlink = (readlink_fn)dlsym(RTLD_NEXT, "readlink");
    }
    ssize_t result = real_readlink(path, buf, size);
    if (
        result < 0
        && errno == ENOENT
        && strncmp(path, "/proc/", 6) == 0
    ) {
        const char *cursor = path + 6;
        if (*cursor >= '0' && *cursor <= '9') {
            while (*cursor >= '0' && *cursor <= '9') {
                cursor++;
            }
            if (strcmp(cursor, "/exe") == 0) {
                result = real_readlink("/proc/self/exe", buf, size);
            }
        }
    }
    return result;
}

